package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct { // 01 DISC-REC, 15 bytes
	DrItem  string          // PIC X(6) @0 len=6
	DrPrice decimal.Decimal // PIC 9(5)V99 @6 len=7
	DrPct   int64           // PIC 9(2) @13 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsDiscount decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99 len=7 = 0
var WsNet decimal.Decimal = decimal.NewFromInt(0) // PIC 9(5)V99 len=7 = 0
var WsTotalNet decimal.Decimal = decimal.NewFromInt(0) // PIC 9(8)V99 len=10 = 0
var WsCount int64 = 0 // PIC 9(3) len=3 = 0
var WsPriceEd string // PIC ZZ,ZZ9.99 len=9
var WsDiscEd string // PIC ZZ,ZZ9.99 len=9
var WsNetEd string // PIC ZZ,ZZ9.99 len=9
var WsTotalEd string // PIC ZZ,ZZZ,ZZ9.99 len=13

// file handling
var discRec DiscRec
var discFileLines []string
var discFileIdx int
var InputDone bool

func pow10Int(n int) int64 {
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func normalizeDecimalScaled(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	if val.IsZero() {
		return decimal.New(0, -scale)
	}
	neg := val.Sign() < 0
	abs := val.Abs()
	scaled := abs.Shift(scale)
	scaledInt := scaled.IntPart()
	pow := pow10Int(intDigits + int(scale))
	modInt := scaledInt % pow
	res := decimal.New(modInt, -scale)
	if neg {
		res = res.Neg()
	}
	return res
}

func normalizeInt(v int64, digits int) int64 {
	pow := pow10Int(digits)
	return v % pow
}

func formatPic9(v int64, width int) string {
	return fmt.Sprintf("%0*d", width, v)
}

func formatNumericEdited(val decimal.Decimal, pattern string) string {
	dotIdx := strings.Index(pattern, ".")
	var intPattern string
	var fracPattern string
	if dotIdx >= 0 {
		intPattern = pattern[:dotIdx]
		fracPattern = pattern[dotIdx+1:]
	} else {
		intPattern = pattern
		fracPattern = ""
	}
	fracDigits := len(fracPattern)
	digitCount := 0
	for _, ch := range intPattern {
		if ch == 'Z' || ch == '9' {
			digitCount++
		}
	}
	neg := val.Sign() < 0
	abs := val.Abs()
	sFixed := abs.StringFixed(int32(fracDigits))
	parts := strings.Split(sFixed, ".")
	intStr := parts[0]
	fracStr := ""
	if len(parts) > 1 {
		fracStr = parts[1]
	} else {
		fracStr = strings.Repeat("0", fracDigits)
	}
	if len(intStr) > digitCount {
		intStr = intStr[len(intStr)-digitCount:]
	}
	if len(intStr) < digitCount {
		intStr = strings.Repeat("0", digitCount-len(intStr)) + intStr
	}
	runes := make([]rune, len(intPattern))
	var digitPos []int
	digitIdx := 0
	for i, ch := range intPattern {
		if ch == 'Z' || ch == '9' {
			runes[i] = rune(intStr[digitIdx])
			digitPos = append(digitPos, i)
			digitIdx++
		} else if ch == ',' {
			runes[i] = ','
		} else {
			runes[i] = ch
		}
	}
	firstNonZeroIdx := -1
	for idx, pos := range digitPos {
		if runes[pos] != '0' {
			firstNonZeroIdx = idx
			break
		}
	}
	if firstNonZeroIdx == -1 {
		firstNonZeroIdx = len(digitPos) - 1
	}
	for idx, pos := range digitPos {
		if idx < firstNonZeroIdx {
			if intPattern[pos] == 'Z' {
				runes[pos] = ' '
			}
		}
	}
	for i, ch := range intPattern {
		if ch == ',' {
			allSpaces := true
			for _, pos := range digitPos {
				if pos < i {
					if runes[pos] != ' ' {
						allSpaces = false
						break
					}
				}
			}
			if allSpaces {
				runes[i] = ' '
			} else {
				runes[i] = ','
			}
		}
	}
	intEdited := string(runes)
	var full string
	if fracDigits > 0 {
		if len(fracStr) < fracDigits {
			fracStr = fracStr + strings.Repeat("0", fracDigits-len(fracStr))
		} else if len(fracStr) > fracDigits {
			fracStr = fracStr[:fracDigits]
		}
		full = intEdited + "." + fracStr
	} else {
		full = intEdited
	}
	if neg {
		rs := []rune(full)
		firstNonSpace := -1
		for i, r := range rs {
			if r != ' ' {
				firstNonSpace = i
				break
			}
		}
		if firstNonSpace == -1 {
			if len(rs) > 0 {
				rs[0] = '-'
			}
		} else if firstNonSpace > 0 {
			rs[firstNonSpace-1] = '-'
		} else {
			rs[0] = '-'
		}
		full = string(rs)
	}
	return full
}

func parsePriceField(s string) decimal.Decimal {
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.New(0, -2)
	}
	n, err := strconv.ParseInt(digits, 10, 64)
	if err != nil {
		n = 0
	}
	return decimal.New(n, -2)
}

func parsePctField(s string) int64 {
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return 0
	}
	n, _ := strconv.ParseInt(digits, 10, 64)
	if len(digits) > 2 {
		n = n % 100
	}
	return n
}

func parseDiscRec(raw string) DiscRec {
	if len(raw) < 15 {
		raw = raw + strings.Repeat(" ", 15-len(raw))
	} else if len(raw) > 15 {
		raw = raw[:15]
	}
	item := raw[0:6]
	priceStr := raw[6:13]
	pctStr := raw[13:15]
	return DiscRec{
		DrItem:  item,
		DrPrice: parsePriceField(priceStr),
		DrPct:   parsePctField(pctStr),
	}
}

func readLines(filename string) ([]string, error) {
	data, err := os.ReadFile(filename)
	if err != nil {
		return nil, err
	}
	s := string(data)
	s = strings.ReplaceAll(s, "\r\n", "\n")
	s = strings.ReplaceAll(s, "\r", "\n")
	if s == "" {
		return []string{}, nil
	}
	var lines []string
	start := 0
	for i, ch := range s {
		if ch == '\n' {
			lines = append(lines, s[start:i])
			start = i + 1
		}
	}
	if start < len(s) {
		lines = append(lines, s[start:])
	}
	return lines, nil
}

func ReadPara() {
	if discFileIdx >= len(discFileLines) {
		WsEofFlag = "Y"
		InputDone = true
		return
	}
	raw := discFileLines[discFileIdx]
	discFileIdx++
	discRec = parseDiscRec(raw)
}

func ProcessPara() {
	tmpDiscountUnrounded := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	wsDiscountRounded := tmpDiscountUnrounded.Round(2)
	WsDiscount = normalizeDecimalScaled(wsDiscountRounded, 5, 2)

	tmpNet := discRec.DrPrice.Sub(WsDiscount)
	tmpNetTrunc := tmpNet.Truncate(2)
	WsNet = normalizeDecimalScaled(tmpNetTrunc, 5, 2)

	sumTotal := WsTotalNet.Add(WsNet)
	sumTrunc := sumTotal.Truncate(2)
	WsTotalNet = normalizeDecimalScaled(sumTrunc, 8, 2)

	WsCount = normalizeInt(WsCount+1, 3)

	WsPriceEd = formatNumericEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatNumericEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatNumericEdited(WsNet, "ZZ,ZZ9.99")

	pctStr := formatPic9(discRec.DrPct, 2)
	line := discRec.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Fprint(os.Stdout, line+"\n")

	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatNumericEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := formatPic9(WsCount, 3)
	line := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Fprint(os.Stdout, line+"\n")
}

func MainPara() {
	lines, err := readLines("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	discFileLines = lines
	discFileIdx = 0
	ReadPara()
	for !InputDone {
		ProcessPara()
	}
	SummaryPara()
}

func main() {
	MainPara()
}
